-- =============================================================================
-- MedVoice AI — Supabase SQL Database Schema & 50 Patient Seed Records
-- Run this script in your Supabase Project:
-- Supabase Dashboard -> SQL Editor -> New Query -> Paste & Run
-- Project URL: https://ubtgoswxrkzoxhptcxpn.supabase.co
-- =============================================================================

-- 1. Create call_reports table
CREATE TABLE IF NOT EXISTS public.call_reports (
  id TEXT PRIMARY KEY,
  patient_id TEXT NOT NULL,
  patient_name TEXT NOT NULL,
  call_sid TEXT,
  recording_url TEXT,
  clinical_summary TEXT,
  urgency_level TEXT DEFAULT 'LOW',
  symptoms_reported JSONB DEFAULT '[]'::jsonb,
  question_responses JSONB DEFAULT '[]'::jsonb,
  guidance_delivered JSONB DEFAULT '[]'::jsonb,
  follow_up_required BOOLEAN DEFAULT false,
  appointment_booked JSONB DEFAULT '{}'::jsonb,
  guardrail_alerts JSONB DEFAULT '[]'::jsonb,
  transcript JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Create comprehensive patients table
CREATE TABLE IF NOT EXISTS public.patients (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  age INTEGER,
  gender TEXT,
  phone TEXT,
  mob_no TEXT,
  address TEXT,
  blood_group TEXT,
  current_health_condition TEXT,
  feedback_given_last_time TEXT,
  current_medication JSONB DEFAULT '[]'::jsonb,
  previous_medical_history JSONB DEFAULT '[]'::jsonb,
  allergies JSONB DEFAULT '[]'::jsonb,
  emergency_contact JSONB DEFAULT '{}'::jsonb,
  last_visit_date DATE,
  consultation_reason TEXT,
  consultation_context TEXT,
  required_questions JSONB DEFAULT '[]'::jsonb,
  approved_guidance JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Add any missing columns if the table already existed with fewer fields
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS gender TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS mob_no TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS blood_group TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS current_health_condition TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS feedback_given_last_time TEXT;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS current_medication JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS previous_medical_history JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS allergies JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS emergency_contact JSONB DEFAULT '{}'::jsonb;
ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS last_visit_date DATE;

-- 3. Create indexes for high-speed queries
CREATE INDEX IF NOT EXISTS idx_call_reports_patient_id ON public.call_reports (patient_id);
CREATE INDEX IF NOT EXISTS idx_call_reports_created_at ON public.call_reports (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_patients_name ON public.patients (name);
CREATE INDEX IF NOT EXISTS idx_patients_phone ON public.patients (phone);

-- 4. Enable Row Level Security (RLS)
ALTER TABLE public.call_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY;

-- 5. Create permissive RLS policies (allow full access for service_role and anon/authenticated)
DROP POLICY IF EXISTS "Allow service role full access on call_reports" ON public.call_reports;
CREATE POLICY "Allow service role full access on call_reports" 
  ON public.call_reports 
  FOR ALL 
  USING (true) 
  WITH CHECK (true);

DROP POLICY IF EXISTS "Allow service role full access on patients" ON public.patients;
CREATE POLICY "Allow service role full access on patients" 
  ON public.patients 
  FOR ALL 
  USING (true) 
  WITH CHECK (true);

-- 6. Insert 50 Complete Clinical Patient Profiles
INSERT INTO public.patients (
  id, name, age, gender, phone, mob_no, address, blood_group,
  current_health_condition, feedback_given_last_time,
  current_medication, previous_medical_history, allergies, emergency_contact,
  last_visit_date, consultation_reason, consultation_context,
  required_questions, approved_guidance
)
VALUES
('pat_001', 'Naman Pilania', 24, 'Male', '+919140511451', '+919140511451', 'Flat 402, Royal Palm Residency, Bandra West, Mumbai, MH 400050', 'B+', 'Post-Discharge Chronic Fatigue & Dehydration Recovery', 'Maintain oral hydration with at least 3 liters of fluids daily, take multivitamins post breakfast, avoid strenuous gym training for 5 days, report persistent dizziness immediately.', '[{"name":"Oral Rehydration Salts (ORS)","dosage":"1 sachet in 1L water","frequency":"Daily morning"},{"name":"Becosules Multivitamin + Zinc","dosage":"1 capsule","frequency":"OD after breakfast"},{"name":"Paracetamol 650mg","dosage":"1 tablet","frequency":"SOS for body ache (max 3/day)"}]'::jsonb, '["Acute viral gastroenteritis (Discharged Oct 2026)","No prior surgical interventions","No history of cardiac, renal, or endocrine disorders"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Pooja Pilania","relation":"Family","phone":"+919876543210"}'::jsonb, '2026-10-28', 'Post-Discharge Fatigue & Recovery Check-in', 'Patient was discharged today following treatment for acute dehydration and fatigue. Assess energy recovery, fluid intake adherence, and absence of dizziness.', '["How is your energy level feeling right now compared to when you were discharged?","Have you been able to take your prescribed fluids and vitamin capsules today?","Are you experiencing any lightheadedness, nausea, or headache?"]'::jsonb, '["Continue regular fluid and electrolyte intake throughout the afternoon.","Get ample physical rest and avoid lifting or intense exertion today.","If severe weakness or lightheadedness returns, contact the care team immediately."]'::jsonb),
('pat_002', 'Rajesh Iyer', 56, 'Male', '+919820144321', '+919820144321', 'B-12 Hiranandani Gardens, Powai, Mumbai, MH 400076', 'O+', 'Essential Hypertension (Stage 2) & Dyslipidemia', 'Strictly limit dietary sodium to under 2 grams daily, take morning Telmisartan before 9 AM, log blood pressure morning and evening, walk 40 minutes daily.', '[{"name":"Telmisartan 40mg + Amlodipine 5mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Atorvastatin 20mg","dosage":"1 tablet","frequency":"OD at bedtime"},{"name":"Ecosprin 75mg","dosage":"1 tablet","frequency":"OD post lunch"}]'::jsonb, '["Hypertension diagnosed 2019","Dyslipidemia diagnosed 2021","Paternal history of early coronary artery disease"]'::jsonb, '["ACE Inhibitors (caused dry cough)"]'::jsonb, '{"name":"Lakshmi Iyer","relation":"Spouse","phone":"+919820144322"}'::jsonb, '2026-10-22', 'Hypertension & Lipid Follow-up', 'Checking compliance on Telmisartan-Amlodipine combination, pedal edema monitoring, and morning blood pressure trends.', '["What was your blood pressure reading this morning?","Have you noticed any ankle swelling or dizziness when standing up?","Are you taking your cholesterol medication every night before bed?"]'::jsonb, '["Target blood pressure is below 130/80 mmHg.","Elevate legs for 20 minutes in the evening if mild ankle puffiness occurs.","Report systolic BP consistently above 160 to clinic."]'::jsonb),
('pat_003', 'Priya Nair', 34, 'Female', '+919711209845', '+919711209845', '74 Indiranagar 100ft Road, Bengaluru, KA 560038', 'A+', 'Gestational Diabetes Mellitus (28 Weeks) & Mild Anemia', 'Record 4-point glucose log (fasting and 2 hours post-meals), maintain complex carbohydrate diet, take iron tablet with vitamin C juice, avoid taking iron with dairy.', '[{"name":"Insulin Aspart (Novorapid)","dosage":"4 units","frequency":"TID with major meals"},{"name":"Ferrous Ascorbate 100mg + Folic Acid","dosage":"1 tablet","frequency":"OD mid-afternoon"},{"name":"Calcium Carbonate 500mg + Vit D3","dosage":"1 tablet","frequency":"BD post meals"}]'::jsonb, '["Polycystic Ovarian Syndrome (PCOS)","First pregnancy (Primigravida), 28 weeks gestation","No history of chronic hypertension"]'::jsonb, '["Sulfa antibiotics"]'::jsonb, '{"name":"Gautam Nair","relation":"Spouse","phone":"+919711209846"}'::jsonb, '2026-10-25', 'Gestational Diabetes & Fetal Well-being Follow-up', '28-week antenatal check. Inquire about blood sugar logs, fetal movements, and tolerance to iron therapy.', '["What was your fasting blood sugar reading this morning?","Are you feeling regular fetal movements after every meal?","Have you experienced any episodes of hypoglycemia like trembling or sweating?"]'::jsonb, '["Target fasting glucose is strictly under 95 mg/dL; post-meal under 120 mg/dL.","Always keep glucose tablets or fruit juice within reach in case of sugar drops.","Do not skip snacks between main meals."]'::jsonb),
('pat_004', 'Marcus Brody', 48, 'Male', '+15550148291', '+15550148291', '742 Evergreen Terrace, Springfield, OR 97477', 'O-', 'Type 2 Diabetes Mellitus & Peripheral Neuropathy', 'Started on Metformin 500mg BID with meals. Check feet daily for blisters or cuts, report tingling sensations or gastrointestinal upset.', '[{"name":"Metformin 500mg Extended Release","dosage":"1 tablet","frequency":"BD with meals"},{"name":"Pregabalin 75mg","dosage":"1 capsule","frequency":"OD at bedtime"},{"name":"Methylcobalamin 1500mcg","dosage":"1 tablet","frequency":"OD morning"}]'::jsonb, '["Type 2 Diabetes diagnosed 2020","Diabetic sensory neuropathy diagnosed 2024","Mild non-proliferative diabetic retinopathy"]'::jsonb, '["Penicillin","Amoxicillin"]'::jsonb, '{"name":"Sarah Brody","relation":"Daughter","phone":"+15550148299"}'::jsonb, '2026-10-20', 'Diabetes Medication Tolerance & Foot Check', 'Reviewing Metformin GI tolerance, fasting sugar numbers, and foot care compliance.', '["Have you noticed any nausea, diarrhea, or stomach cramps with the new Metformin dose?","What was your fasting glucose reading today?","Did you inspect the soles of your feet today for any redness or pressure spots?"]'::jsonb, '["Take Metformin halfway through your meals to avoid stomach upset.","Wear seamless diabetic socks and comfortable supportive shoes.","If blood sugar goes above 250 mg/dL consistently, alert your physician."]'::jsonb),
('pat_005', 'Sophia Martinez', 31, 'Female', '+15550173620', '+15550173620', '1244 Sunset Boulevard, Los Angeles, CA 90026', 'A-', 'Post-Operative Arthroscopic Meniscectomy (Day 6)', 'Keep surgical dressing dry and clean. Ice the knee 20 minutes every 3 hours. Elevate leg above heart level when resting. Start gentle ankle pumps.', '[{"name":"Ibuprofen 600mg","dosage":"1 tablet","frequency":"TID with food PRN"},{"name":"Pantoprazole 40mg","dosage":"1 tablet","frequency":"OD before breakfast"},{"name":"Acetaminophen 500mg","dosage":"1-2 tablets","frequency":"Q6H PRN breakthrough pain"}]'::jsonb, '["Left knee medial meniscus tear (Sports injury Aug 2026)","Arthroscopic partial meniscectomy performed 6 days ago","No chronic medical conditions"]'::jsonb, '["Codeine (severe nausea)"]'::jsonb, '{"name":"Elena Martinez","relation":"Mother","phone":"+15550173699"}'::jsonb, '2026-10-23', 'Post-Surgical Knee Recovery Follow-up', 'Post-op day 6 check. Assess pain score (1-10), surgical site healing, and rule out deep vein thrombosis (DVT) red flags.', '["On a scale of 1 to 10, what is your current knee pain level?","Is the incision dressing clean and dry, without any oozing or redness?","Are you experiencing any calf tenderness, swelling, or sudden chest pain?"]'::jsonb, '["Continue cold compression 20 minutes on, 20 minutes off.","Keep using your crutches when moving around to avoid premature weight loading.","Physical therapy evaluation is scheduled for next Monday."]'::jsonb),
('pat_006', 'Vikram Malhotra', 62, 'Male', '+919810234567', '+919810234567', 'C-45 Greater Kailash 1, New Delhi, DL 110048', 'AB+', 'Coronary Artery Disease (Post-PTCA Stent - Month 3)', 'Do not miss dual antiplatelet therapy under any circumstance, maintain low-cholesterol diet, monitor for unexplained bruising or bleeding.', '[{"name":"Ticagrelor 90mg","dosage":"1 tablet","frequency":"BD morning & evening"},{"name":"Aspirin 75mg Gastro-resistant","dosage":"1 tablet","frequency":"OD post lunch"},{"name":"Rosuvastatin 20mg","dosage":"1 tablet","frequency":"OD night"},{"name":"Metoprolol Succinate 50mg","dosage":"1 tablet","frequency":"OD morning"}]'::jsonb, '["Acute anterior wall myocardial infarction with DES to LAD (July 2026)","Mild left ventricular systolic dysfunction (LVEF 48%)","Ex-smoker (Quit 3 months ago)"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Rohit Malhotra","relation":"Son","phone":"+919810234568"}'::jsonb, '2026-10-18', 'Post-Cardiac Stent 3-Month Follow-up', 'Assess cardiac stability, exercise tolerance, absence of angina or dyspnea on exertion, and medication compliance.', '["Have you experienced any chest pressure, tightness, or breathlessness during your daily walks?","Are you taking your blood thinner tablets on time twice every day?","Have you noticed any unusual bleeding from gums or black-colored stools?"]'::jsonb, '["Any chest pain radiating to the left arm or jaw requires immediate ER evaluation.","Never discontinue Ticagrelor without cardiologist consultation.","Maintain a 30-minute brisk walk within comfortable breathing limits."]'::jsonb),
('pat_007', 'Sunita Deshmukh', 51, 'Female', '+919822345678', '+919822345678', 'Flat 301, Prabhat Road, Lane 4, Pune, MH 411004', 'B-', 'Hypothyroidism (Hashimoto''s) & Primary Osteoarthritis', 'Take Levothyroxine on an empty stomach with plain water at least 45 minutes before breakfast or tea. Perform quadriceps strengthening exercises.', '[{"name":"Levothyroxine Sodium 75mcg","dosage":"1 tablet","frequency":"OD early morning empty stomach"},{"name":"Glucosamine + Chondroitin","dosage":"1 tablet","frequency":"OD after lunch"},{"name":"Cholecalciferol 60,000 IU","dosage":"1 sachet in milk","frequency":"Once weekly for 8 weeks"}]'::jsonb, '["Hashimoto''s Thyroiditis diagnosed 2017","Bilateral knee osteoarthritis (Grade 2)","Total abdominal hysterectomy (2018)"]'::jsonb, '["Iodinated radiographic contrast"]'::jsonb, '{"name":"Anand Deshmukh","relation":"Spouse","phone":"+919822345679"}'::jsonb, '2026-10-14', 'Thyroid & Joint Health Review', 'Inquire about morning thyroid medicine timing, knee stiffness, and cold intolerance.', '["Are you taking your thyroid tablet first thing in the morning with plain water?","How long do you wait after your tablet before drinking tea or having breakfast?","Are you experiencing excessive tiredness, hair fall, or joint stiffness in the morning?"]'::jsonb, '["Calcium or iron supplements must be taken at least 4 hours away from thyroid medicine.","Perform gentle knee flexion exercises twice daily to preserve joint mobility.","Repeat thyroid profile (TSH) is due next month."]'::jsonb),
('pat_008', 'David Miller', 59, 'Male', '+15550183921', '+15550183921', '389 Pine Crest Drive, Seattle, WA 98101', 'O+', 'Congestive Heart Failure (NYHA Class II) & CKD Stage 3a', 'Weigh yourself every single morning after first urination. Strict fluid restriction to 1.5 liters per day. Report weight gain >2 lbs in 24 hours.', '[{"name":"Sacubitril / Valsartan (Entresto) 24/26mg","dosage":"1 tablet","frequency":"BD morning & night"},{"name":"Furosemide 40mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Spironolactone 25mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Empagliflozin 10mg","dosage":"1 tablet","frequency":"OD morning"}]'::jsonb, '["Ischemic cardiomyopathy (LVEF 35%)","Chronic kidney disease Stage 3a (Baseline eGFR 52)","Biatrial enlargement"]'::jsonb, '["Sulfa drugs (causes severe skin rash)"]'::jsonb, '{"name":"Karen Miller","relation":"Spouse","phone":"+15550183999"}'::jsonb, '2026-10-24', 'Heart Failure Vitals & Fluid Status Check', 'Assess morning dry weight trend, orthopnea (sleeping on extra pillows), paroxysmal nocturnal dyspnea, and peripheral edema.', '["What did your scale read this morning, and how does that compare to yesterday?","How many pillows are you sleeping on to breathe comfortably at night?","Have you noticed any swelling in your ankles or tightness in your shoes?"]'::jsonb, '["A weight gain of more than 2 to 3 pounds overnight indicates fluid retention; call care team.","Stay strictly within your 1.5 liter total daily fluid limit.","Take your diuretic (Furosemide) in the morning to avoid waking up at night."]'::jsonb),
('pat_009', 'Kavita Patel', 28, 'Female', '+919879123450', '+919879123450', '15 Navrangpura, Near Stadium Crossroad, Ahmedabad, GJ 380009', 'B+', 'Persistent Bronchial Asthma & Allergic Rhinitis', 'Always rinse mouth with water and spit after using Budesonide inhaler to prevent oral thrush. Keep Salbutamol inhaler with you at all times.', '[{"name":"Budesonide 200mcg + Formoterol 6mcg Inhaler","dosage":"2 puffs","frequency":"BD morning and night"},{"name":"Levocetirizine 5mg + Montelukast 10mg","dosage":"1 tablet","frequency":"OD at bedtime"},{"name":"Salbutamol 100mcg Reliever Inhaler","dosage":"2 puffs","frequency":"SOS for sudden wheeze"}]'::jsonb, '["Childhood bronchial asthma","Severe dust mite and pollen allergy","No hospitalizations in the last 12 months"]'::jsonb, '["Aspirin & NSAIDs (induces bronchospasm)"]'::jsonb, '{"name":"Bhaven Patel","relation":"Brother","phone":"+919879123451"}'::jsonb, '2026-10-19', 'Asthma Control & Inhaler Technique Check', 'Assess daytime wheezing, nighttime awakenings, and frequency of reliever inhaler usage in the past week.', '["How many times in the past 7 days have you had to use your quick-relief Salbutamol inhaler?","Have you been waking up in the middle of the night with chest tightness or coughing?","Are you rinsing your mouth thoroughly after using your morning and evening inhaler?"]'::jsonb, '["Using your rescue inhaler more than twice a week indicates uncontrolled inflammation.","Rinse and gargle after steroid inhaler to prevent oral candida.","Avoid exposure to burning incense, cigarette smoke, or heavy dust."]'::jsonb),
('pat_010', 'Arvind Swaminathan', 67, 'Male', '+919444156789', '+919444156789', '22 Luz Church Road, Mylapore, Chennai, TN 600004', 'AB-', 'Benign Prostatic Hyperplasia (BPH) & Chronic Gout', 'Take Tamsulosin 30 minutes after dinner to reduce orthostatic lightheadedness. Avoid purine-rich foods (red meat, seafood) and stay well hydrated.', '[{"name":"Tamsulosin 0.4mg + Dutasteride 0.5mg","dosage":"1 capsule","frequency":"OD post dinner"},{"name":"Febuxostat 40mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Colchicine 0.5mg","dosage":"1 tablet","frequency":"SOS for acute joint flare"}]'::jsonb, '["Recurrent gouty arthritis (Great toe & right ankle)","BPH with moderate lower urinary tract symptoms","Mild bilateral sensorineural hearing loss"]'::jsonb, '["Allopurinol (developed severe pruritic rash)"]'::jsonb, '{"name":"Sowmya Swaminathan","relation":"Daughter","phone":"+919444156790"}'::jsonb, '2026-10-16', 'Urinary Flow & Uric Acid Follow-up', 'Assess nocturia frequency (times waking at night to urinate), urinary hesitancy, and absence of acute joint swelling.', '["How many times per night do you currently wake up to use the bathroom?","Have you noticed any joint tenderness, redness, or heat in your big toe or ankles?","Are you feeling any dizziness when getting out of bed in the morning?"]'::jsonb, '["Drink plenty of water during the daytime, but taper fluids after 8 PM to reduce nocturia.","Take your prostate medication consistently after dinner.","Avoid dehydration as it triggers acute gout crystal formation."]'::jsonb),
('pat_011', 'Meera Joshi', 44, 'Female', '+919833456789', '+919833456789', 'Flat 5B, Sagar Darshan, Worli Sea Face, Mumbai, MH 400030', 'A+', 'Chronic Migraine with Visual Aura & Cervical Spondylosis', 'Maintain a migraine trigger diary. Avoid skipping meals or disrupted sleep. Take Propranolol consistently for prophylaxis, take Zolmitriptan at earliest onset.', '[{"name":"Propranolol Extended Release 40mg","dosage":"1 capsule","frequency":"OD morning"},{"name":"Zolmitriptan 2.5mg Nasal Spray","dosage":"1 spray","frequency":"SOS at aura onset"},{"name":"Naproxen 250mg","dosage":"1 tablet","frequency":"SOS with food for neck spasm"}]'::jsonb, '["Episodic migraine progressed to chronic (2022)","Cervical disc bulge at C5-C6","No hypertension or vascular malformations"]'::jsonb, '["Caffeine-based combinations (cause palpitations)"]'::jsonb, '{"name":"Sameer Joshi","relation":"Spouse","phone":"+919833456780"}'::jsonb, '2026-10-21', 'Migraine Frequency & Prophylaxis Review', 'Assess number of migraine days in the past 14 days, efficacy of rescue nasal spray, and neck posture.', '["How many headache episodes have you experienced over the last two weeks?","Did you notice the flashing light aura before your last headache?","Is the daily preventive tablet helping reduce the headache intensity?"]'::jsonb, '["Take your rescue triptan at the first sign of aura rather than waiting for severe pain.","Maintain a dark, quiet room during acute episodes.","Do ergonomic neck stretches every 2 hours if working on screens."]'::jsonb),
('pat_012', 'Amit Singhania', 53, 'Male', '+919830123456', '+919830123456', '18 Ballygunge Circular Road, Kolkata, WB 700019', 'O+', 'Non-Alcoholic Fatty Liver Disease (Grade 2) & Metabolic Syndrome', 'Gradual weight reduction target of 5-7% over 3 months. Eliminate refined sugars, fried street foods, and sweetened beverages. Daily brisk walking 45 mins.', '[{"name":"Saroglitazar 4mg","dosage":"1 tablet","frequency":"OD before breakfast"},{"name":"Vitamin E (d-alpha tocopherol) 400 IU","dosage":"1 capsule","frequency":"OD post lunch"},{"name":"Metformin 500mg","dosage":"1 tablet","frequency":"BD with meals"}]'::jsonb, '["NAFLD diagnosed on ultrasound (2023)","Elevated baseline ALT/AST enzymes","Borderline fasting hyperglycemia (HbA1c 6.4%)"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Ritu Singhania","relation":"Spouse","phone":"+919830123457"}'::jsonb, '2026-10-12', 'Liver Health & Weight Management Check', 'Monitor lifestyle adherence, weight changes, upper right quadrant abdomen heaviness, and energy levels.', '["Have you been able to incorporate the 45-minute daily brisk walking routine?","Have you experienced any dull ache or discomfort under your right ribs?","What changes have you made to eliminate refined sugars and sodas?"]'::jsonb, '["Sustainable lifestyle and weight loss is the most effective therapy for fatty liver.","Avoid over-the-counter pain relievers or unnecessary herbal supplements without doctor advice.","Repeat liver function tests are due in 6 weeks."]'::jsonb),
('pat_013', 'Sneha Kulkarni', 39, 'Female', '+919890123456', '+919890123456', 'Plot 18, Kothrud Dahanukar Colony, Pune, MH 411038', 'B+', 'Rheumatoid Arthritis (Active Seropositive) & Raynaud''s Phenomenon', 'Take Methotrexate strictly once weekly on the same day (Saturdays). Take Folic acid on non-methotrexate days. Keep hands warm in cold environments.', '[{"name":"Methotrexate 15mg","dosage":"3 tablets of 5mg","frequency":"Once weekly on Saturday night"},{"name":"Folic Acid 5mg","dosage":"1 tablet","frequency":"OD Sunday through Friday"},{"name":"Hydroxychloroquine 200mg","dosage":"1 tablet","frequency":"OD with dinner"},{"name":"Deflazacort 6mg","dosage":"1 tablet","frequency":"OD morning (tapering)"}]'::jsonb, '["Seropositive Rheumatoid Arthritis diagnosed 2021","Secondary Raynaud''s phenomenon in digits","Mild osteopenia"]'::jsonb, '["Sulphasalazine (severe gastrointestinal intolerance)"]'::jsonb, '{"name":"Nilesh Kulkarni","relation":"Spouse","phone":"+919890123457"}'::jsonb, '2026-10-17', 'DMARD Safety & Morning Stiffness Review', 'Monitor duration of morning joint stiffness, hand digit color changes, and liver safety on weekly Methotrexate.', '["How long does the morning stiffness in your finger and wrist joints last after waking up?","Are you taking your Methotrexate only on Saturday nights with the rest on folic acid?","Have you noticed any mouth ulcers, hair thinning, or nausea after your weekly dose?"]'::jsonb, '["Never take Methotrexate daily; it is strictly a once-weekly medication.","Wear warm gloves if entering air-conditioned or cold rooms to prevent Raynaud''s spasm.","Routine CBC and LFT blood tests must be completed every 2 months."]'::jsonb),
('pat_014', 'Robert Chen', 64, 'Male', '+15550192834', '+15550192834', '512 Grant Avenue, San Francisco, CA 94108', 'A-', 'Chronic Obstructive Pulmonary Disease (GOLD Stage II) & Emphysema', 'Use Triple Therapy inhaler daily without skipping. Practice pursed-lip breathing during exertion. Keep oxygen saturation meter accessible.', '[{"name":"Fluticasone/Umeclidinium/Vilanterol (Trelegy Ellipta)","dosage":"1 inhalation","frequency":"OD every morning"},{"name":"Albuterol Inhaler","dosage":"2 puffs","frequency":"Q4H PRN shortness of breath"},{"name":"Azithromycin 250mg","dosage":"1 tablet","frequency":"Monday/Wednesday/Friday for exacerbation prophylaxis"}]'::jsonb, '["COPD diagnosed 2018 (35 pack-year smoking history, quit 2019)","Pneumococcal vaccination up to date","Hospital admission for COPD exacerbation in Dec 2025"]'::jsonb, '["Cephalosporins (rash)"]'::jsonb, '{"name":"Lisa Chen","relation":"Daughter","phone":"+15550192899"}'::jsonb, '2026-10-23', 'COPD Symptom Tracking & Sputum Review', 'Assess changes in sputum color/volume, walking distance without stopping, and resting pulse oximetry readings.', '["What is your oxygen saturation reading on your finger pulse oximeter today?","Has there been any increase in the amount or change to a yellow/green color in your mucus?","How many times did you need your quick-acting rescue inhaler yesterday?"]'::jsonb, '["If pulse oximetry drops below 90% at rest, sit upright and use rescue inhaler; alert doctor.","Pursed-lip breathing helps expel trapped air from the lungs during walking.","Annual influenza shot is recommended this week."]'::jsonb),
('pat_015', 'Fatima Al-Mansoor', 41, 'Female', '+919845012345', '+919845012345', 'Villa 12, Palm Meadows, Whitefield, Bengaluru, KA 560066', 'B+', 'Generalized Anxiety Disorder & Mild Gastroesophageal Reflux (GERD)', 'Take Escitalopram consistently every morning. Avoid caffeine after 2 PM. Avoid lying down for 2 hours after dinner to prevent acid reflux.', '[{"name":"Escitalopram 10mg","dosage":"1 tablet","frequency":"OD morning post breakfast"},{"name":"Esomeprazole 40mg","dosage":"1 tablet","frequency":"OD 30 mins before dinner"},{"name":"Clonazepam 0.25mg","dosage":"1 tablet","frequency":"SOS severe panic (max 2/week)"}]'::jsonb, '["GAD diagnosed 2023","Endoscopy confirmed mild reflux esophagitis (Jan 2026)","No history of cardiac arrhythmias"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Zaid Al-Mansoor","relation":"Spouse","phone":"+919845012346"}'::jsonb, '2026-10-20', 'Anxiety & Reflux Medication Follow-up', 'Assess sleep quality, daytime panic symptoms, nighttime heartburn, and medication tolerability.', '["How have your sleep quality and morning anxiety levels been feeling this week?","Are you experiencing any sour taste or burning sensation in your chest at night?","Have you needed to use your backup calming tablet in the past few days?"]'::jsonb, '["Elevate the head of your bed 6 inches to naturally curb nighttime acid reflux.","Escitalopram takes 4 to 6 weeks for full therapeutic stabilization; do not discontinue abruptly.","Practice 4-7-8 diaphragmatic breathing during moments of heightened tension."]'::jsonb),
('pat_016', 'Ananya Roy', 36, 'Female', '+9198100054', '+9198100054', 'Street 10, Sector 1, Kolkata, WB', 'O+', 'Post-Operative Laparoscopic Cholecystectomy (Day 8)', 'Follow prescribed medication doses strictly, monitor daily symptom logs, and reach out to the clinic if discomfort arises.', '[{"name":"Paracetamol 650mg","dosage":"1 tablet","frequency":"TID PRN pain"},{"name":"Cefuroxime Axetil 500mg","dosage":"1 tablet","frequency":"BD for 3 more days"},{"name":"Pantoprazole 40mg","dosage":"1 tablet","frequency":"OD before breakfast"}]'::jsonb, '["History of Post-Operative Laparoscopic Cholecystectomy","Routine annual blood panels within acceptable range","No documented contraindications"]'::jsonb, '["Penicillin"]'::jsonb, '{"name":"Contact for Ananya","relation":"Family","phone":"+9198100099"}'::jsonb, '2026-10-10', 'Post-Cholecystectomy Wound & Diet Review', 'Ananya Roy (36y Female): Post-op day 8 after gall bladder removal. Assess incision healing, absence of jaundice, and tolerance to low-fat foods.', '["Are your four small surgical incision sites clean, dry, and healing without redness?","Have you noticed any yellowing of your eyes or skin, or dark-colored urine?","Are you able to digest light, low-fat meals without nausea or pain?"]'::jsonb, '["Avoid fried, oily, and heavy dairy foods for another 2 to 3 weeks.","Do not lift objects heavier than 5 kg until your surgical clearance.","Stitch removal or check-up is scheduled for day 10."]'::jsonb),
('pat_017', 'Tariq Ansari', 58, 'Male', '+9198102754', '+9198102754', 'Street 11, Sector 4, Lucknow, UP', 'B+', 'Type 2 Diabetes Mellitus with Chronic Microalbuminuria', 'Follow prescribed medication doses strictly, monitor daily symptom logs, and reach out to the clinic if discomfort arises.', '[{"name":"Dapagliflozin 10mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Telmisartan 40mg","dosage":"1 tablet","frequency":"OD morning"},{"name":"Linagliptin 5mg","dosage":"1 tablet","frequency":"OD post lunch"}]'::jsonb, '["History of Type 2 Diabetes Mellitus with Chronic Microalbuminuria","Routine annual blood panels within acceptable range","No documented contraindications"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Contact for Tariq","relation":"Family","phone":"+9198102799"}'::jsonb, '2026-10-11', 'Renal Protection & Glycemic Review', 'Tariq Ansari (58y Male): Checking renal protective medication compliance, urinary hygiene on SGLT2 inhibitor, and glucose stability.', '["Have you noticed any burning sensation, increased frequency, or pain when urinating?","What was your average blood sugar reading over the last 3 days?","Are you drinking at least 2.5 liters of clean water daily with the Dapagliflozin?"]'::jsonb, '["Drink adequate water to prevent urinary tract infections while taking Dapagliflozin.","Telmisartan helps protect your kidneys from protein leakage.","Report any fever or cloudy urine immediately."]'::jsonb),
('pat_018', 'Aisha Khan', 29, 'Female', '+9198105454', '+9198105454', 'Street 12, Sector 7, Hyderabad, TS', 'A+', 'Chronic Atrial Fibrillation (Rate Controlled) on Anticoagulation', 'Follow prescribed medication doses strictly, monitor daily symptom logs, and reach out to the clinic if discomfort arises.', '[{"name":"Apixaban (Eliquis) 5mg","dosage":"1 tablet","frequency":"BD 12 hours apart"},{"name":"Diltiazem Extended Release 120mg","dosage":"1 capsule","frequency":"OD morning"},{"name":"Atorvastatin 10mg","dosage":"1 tablet","frequency":"OD at bedtime"}]'::jsonb, '["History of Chronic Atrial Fibrillation","Routine annual blood panels within acceptable range","No documented contraindications"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Contact for Aisha","relation":"Family","phone":"+9198105499"}'::jsonb, '2026-10-12', 'Cardiac Rhythm & Blood Thinner Monitoring', 'Aisha Khan (29y Female): Assess compliance with twice-daily direct oral anticoagulant (DOAC), absence of palpitations, and check for bleeding signs.', '["Are you taking your blood thinner tablet exactly 12 hours apart every day?","Have you felt your heart racing, fluttering, or skipping beats recently?","Have you noticed any unusual nosebleeds, gum bleeding, or bruises on your arms?"]'::jsonb, '["Never miss a dose of Apixaban because protection against stroke wears off in 24 hours.","Avoid high-impact contact activities to minimize bleeding and hematoma risk.","Check your resting pulse rate; it should typically stay between 60 and 85 bpm."]'::jsonb),
('pat_019', 'Harish Reddy', 63, 'Male', '+9198108154', '+9198108154', 'Street 13, Sector 10, Bengaluru, KA', 'AB+', 'Ulcerative Colitis (Mild-to-Moderate Left Sided) in Remission', 'Follow prescribed medication doses strictly, monitor daily symptom logs, and reach out to the clinic if discomfort arises.', '[{"name":"Mesalamine (5-ASA) 1.2g Extended Release","dosage":"2 tablets","frequency":"BD with food"},{"name":"Mesalamine Suppository 1g","dosage":"1 suppository","frequency":"Once at bedtime"},{"name":"Probiotic VSL#3 Capsule","dosage":"1 capsule","frequency":"BD post meals"}]'::jsonb, '["History of Ulcerative Colitis","Routine annual blood panels within acceptable range","No documented contraindications"]'::jsonb, '["No known drug allergies (NKDA)"]'::jsonb, '{"name":"Contact for Harish","relation":"Family","phone":"+9198108199"}'::jsonb, '2026-10-13', 'Inflammatory Bowel Disease Maintenance', 'Harish Reddy (63y Male): Assess maintenance of bowel remission, stool frequency, absence of rectal bleeding, and abdominal cramping.', '["How many bowel movements are you having in a 24-hour period?","Have you observed any visible blood, mucus, or urgent cramping with stools?","Are you taking your full daily dose of Mesalamine regularly?"]'::jsonb, '["Continue maintenance 5-ASA even when feeling completely asymptomatic to prevent relapse.","Stay hydrated and avoid spicy, raw seed, or gas-producing trigger foods.","Contact the GI team promptly if stool frequency exceeds 4 per day or blood appears."]'::jsonb),
